#!/usr/bin/env python3
# Generated by Claude (AI-assisted); reviewed by the SFL authors before use.
"""Emit the data the HTML book needs to run exercises in the reader's browser.

For each chapter of a built student variant, this writes
`_out/<vol>/student/html/sfl-lean/data/<Chapter>.json` holding:

* `skeleton`: the chapter's code with every theorem proof replaced by `sorry`
  and with `example`s, `#eval`/`#check`-style queries, and the SFLCompat
  teaching commands left out.  An exercise needs the *statements* that come
  before it, not their proofs, and elaborating statements is what keeps a run
  in the browser down to seconds.
* `exercises`: for each exercise, its student code (what the reader edits),
  the offset into `skeleton` where the exercise begins (everything before it is
  the exercise's context), and the line of its `:::::exercise` directive in the
  Verso source (for the "view source" link).
* `blocks`: for each Lean code block in the chapter's text, outside exercises
  and quizzes, its code as the page shows it, its position among the page's
  code blocks, and the offset into `skeleton` where it begins, so that a reader
  can change an example or a given proof and check it against the same context
  an exercise there would get.
* `library`: the skeletons of the chapters this one imports, in import order,
  each wrapped in `section … end` so that one chapter's `open`s and `variable`s
  stop at its end, as they would at a file boundary.

The skeletons are plain source, not `.olean` files, so the browser's Lean need
not be the exact version that built the book.  The same text, concatenated, is
also a single self-contained file that live.lean-lang.org can check, which is
what readers on phones are offered instead of the in-browser editor.

Usage: python3 scripts/web_exercises.py <vol> [<variant>]   (e.g. `lf`)
"""

import bisect
import json
import re
import sys
from html.parser import HTMLParser
from pathlib import Path

# Commands that are dropped from a skeleton.  Each either only prints something
# (`#check`), only demonstrates something (`example`), or is an SFLCompat
# teaching command whose effect does not outlive the command.
DROP = {
    "example", "#check", "#eval", "#print", "#reduce", "#synth", "#guard",
    "#guard_msgs", "#check_failure", "#help", "#exit",
    "sf_expect_failure_in", "sf_recall", "sf_experiment",
}
# Declarations whose proofs are replaced by `sorry`.
PROOF = {"theorem", "lemma"}
# Modifiers that may precede the keyword that names a command.
MODIFIERS = {
    "private", "protected", "public", "noncomputable", "partial", "unsafe",
    "nonrec", "scoped", "local", "meta",
}
# Words that start a top-level command when they begin a line in column 0.
# Anything else in column 0 (`|`, `where`, `deriving`, a closing bracket)
# continues the command above it.
COMMANDS = DROP | PROOF | MODIFIERS | {
    "def", "abbrev", "instance", "inductive", "structure", "class", "axiom",
    "opaque", "namespace", "section", "end", "open", "export", "variable",
    "universe", "set_option", "attribute", "notation", "infix", "infixl",
    "infixr", "prefix", "postfix", "macro", "macro_rules", "syntax", "elab",
    "elab_rules", "declare_syntax_cat", "declare_config_elab", "mutual",
    "initialize", "builtin_initialize", "add_decl_doc", "deriving",
    "omit", "include", "unseal", "seal", "import", "module",
}

EXERCISE_RE = re.compile(
    r"^--  ### Exercise \((\d+) stars?\): (\S+)((?: \([^)]*\))?)(?: ⭐+)?\s*$")
END_RE = re.compile(r"^--  \(End of exercise\)\s*$")
HEADING_RE = re.compile(r"^--  #")
IMPORT_RE = re.compile(r"^(?:public\s+)?(?:meta\s+)?import\s+(?:all\s+)?(\S+)")


def first_word(line):
    """The command keyword of a column-0 line, skipping attributes and a
    leading doc comment marker, or None if the line does not start one."""
    s = line
    if s.startswith("/--") or s.startswith("@["):
        return "decl-prefix"
    m = re.match(r"[#\w.]+", s)
    return m.group(0) if m else None


def attributes_only(line):
    """Whether a line holds `@[…]` attributes and nothing after them, so that
    it joins the declaration on the next line.  `@[simp] theorem …` starts a
    command of its own."""
    s = line.strip()
    while s.startswith("@["):
        depth, k = 0, 0
        for k, c in enumerate(s):
            depth += c == "["
            depth -= c == "]"
            if depth == 0 and c == "]":
                break
        s = s[k + 1:].strip()
    return s == ""


def split_commands(lines):
    """Split a file body into top-level commands.

    Returns a list of (start, end) half-open line ranges.  A command starts at a
    column-0 line that begins with a command keyword, an attribute, or a doc
    comment; a doc comment or attribute line joins the command that follows.
    Column-0 `--` comment lines and plain `/- … -/` block comments between
    commands become commands of their own (kind "comment") so they can be
    dropped without disturbing the code around them."""
    cmds = []
    i, n = 0, len(lines)
    cur = None
    while i < n:
        line = lines[i]
        if line.startswith("/-") and not line.startswith("/--"):
            # A plain or module-doc block comment at top level.
            j = i
            depth = 0
            while j < n:
                depth += lines[j].count("/-") - lines[j].count("-/")
                j += 1
                if depth <= 0:
                    break
            if cur is not None:
                cmds.append((cur, i))
                cur = None
            cmds.append((i, j))
            i = j
            continue
        word = first_word(line) if line[:1] not in ("", " ", "\t") else None
        starts = word is not None and (word in COMMANDS or word == "decl-prefix")
        if line.startswith("--"):
            starts = False
        if starts:
            # An attribute or doc comment stays attached to the command below.
            prev_is_prefix = (cur is not None and i > 0 and
                              all(l.startswith("/--") or attributes_only(l) or l.startswith(" ")
                                  or l.startswith("-/") or not l.strip()
                                  for l in lines[cur:i]))
            if not prev_is_prefix:
                if cur is not None:
                    cmds.append((cur, i))
                cur = i
            if line.startswith("/--") and "-/" not in line:
                # Skip to the end of the doc comment; its lines are not commands.
                while i < n and "-/" not in lines[i]:
                    i += 1
        i += 1
    if cur is not None:
        cmds.append((cur, n))
    return cmds


def keyword(lines, start, end):
    """The keyword that names the command in lines[start:end]."""
    text = "\n".join(lines[start:end])
    text = re.sub(r"/--.*?-/", "", text, flags=re.S)
    while True:
        text = text.lstrip()
        if text.startswith("@["):
            depth, k = 0, 0
            for k, c in enumerate(text):
                depth += c == "["
                depth -= c == "]"
                if depth == 0 and c == "]":
                    break
            text = text[k + 1:]
            continue
        m = re.match(r"[#\w.]+", text)
        if not m:
            return None
        if m.group(0) in MODIFIERS and m.group(0) not in ("scoped", "local"):
            text = text[m.end():]
            continue
        return m.group(0)


OPEN = {"(": ")", "[": "]", "{": "}", "⟨": "⟩", "⦃": "⦄"}
CLOSE = set(OPEN.values())


def statement_of(text):
    """Cut a theorem command just before its proof: at the `:=` outside
    brackets, comments and strings that starts it, at the first
    column-0/indented `|` alternative of an equation-compiler proof, or at a
    `where` that gives the proof's fields (`where mp h := …`)."""
    depth = 0
    # An Imp command in a statement assigns with `:=` too
    # (`{{ Q [x ↦ a] }} x := a {{ Q }}`).  The proof's `:=` starts a tactic
    # block or ends its line, so a `:=` with more code after it on its line
    # starts the proof only when no such `:=` comes later.
    first = None
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if text.startswith("--", i):
            i = text.find("\n", i)
            if i < 0:
                break
            continue
        if text.startswith("/-", i):
            j = text.find("-/", i + 2)
            i = n if j < 0 else j + 2
            continue
        if c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 2 if text[j] == "\\" else 1
            i = j + 1
            continue
        if c in OPEN:
            depth += 1
        elif c in CLOSE:
            depth -= 1
        elif depth == 0 and text.startswith(":=", i):
            if re.match(r"[ \t]*(?:by\b|\n|$)", text[i + 2:]):
                return text[:i].rstrip()
            if first is None:
                first = i
        elif depth == 0 and c == "|" and text[:i].rstrip(" \t").endswith("\n"):
            return text[:i if first is None else first].rstrip()
        elif (depth == 0 and text.startswith("where", i) and text[i - 1:i].isspace()
              and (i + 5 == n or text[i + 5].isspace())):
            return text[:i if first is None else first].rstrip()
        i += 1
    return None if first is None else text[:first].rstrip()


def skeleton_of_command(lines, start, end):
    """The skeleton text of one command, or None if it is dropped."""
    first = lines[start]
    if first.startswith("--") or (first.startswith("/-") and not first.startswith("/--")):
        return None
    kw = keyword(lines, start, end)
    if kw is None or kw in DROP or kw in ("import", "module"):
        return None
    # Full-line prose comments carry no code; leave them out of the skeleton.
    body = [l for l in lines[start:end] if not l.startswith("--")]
    text = "\n".join(body).rstrip()
    if kw in PROOF:
        stmt = statement_of(text)
        if stmt is None:
            raise ValueError(f"no proof found in theorem at line {start + 1}")
        text = stmt + " := by\n  sorry"
    return text


def chapter_header(lines):
    """The chapter's imports (module names and verbatim lines) and the index of
    the first line after its header, which may start with `module`."""
    imports, import_lines, body_start = [], [], 0
    for i, line in enumerate(lines):
        m = IMPORT_RE.match(line)
        if m:
            imports.append(m.group(1))
            import_lines.append(line.strip())
            body_start = i + 1
        elif line.strip() == "module":
            body_start = i + 1
        elif line.strip() and not line.startswith("--"):
            break
    return imports, import_lines, body_start


def find_exercises(lines):
    """(name, stars, flags, header line, first code line, end line) for each
    exercise, as 0-based line indices; the exercise's code is lines[code:end]."""
    out = []
    for i, line in enumerate(lines):
        m = EXERCISE_RE.match(line)
        if not m:
            continue
        j = i + 1
        while j < len(lines) and not END_RE.match(lines[j]) and not HEADING_RE.match(lines[j]):
            j += 1
        out.append((m.group(2), int(m.group(1)), m.group(3).strip(" ()"), i, i + 1, j))
    return out


def trim_blank(lines):
    while lines and not lines[0].strip():
        lines = lines[1:]
    while lines and not lines[-1].strip():
        lines = lines[:-1]
    return lines


# SFLCompat's teaching commands, each followed by an indented block, and how
# that block is introduced once it is shown as a comment.
COMPAT_BLOCKS = {
    "sf_recall": "Recalled from earlier (already defined above):",
    "sf_expect_failure_in": "Lean rejects the following (that is the point):",
    "sf_experiment": "An experiment whose effect does not outlast it:",
}


def compat_as_comment(code_lines):
    """Show each SFLCompat teaching block in exercise code as a comment.

    These commands restate a declaration (`sf_recall`), show code Lean rejects
    (`sf_expect_failure_in`), or try something and then undo it
    (`sf_experiment`).  None leaves anything behind that later code relies on,
    so as comments they still read the same and no longer need SFLCompat,
    which the browser does not load."""
    out, i = [], 0
    while i < len(code_lines):
        intro = COMPAT_BLOCKS.get(code_lines[i].rstrip())
        if intro is None:
            out.append(code_lines[i])
            i += 1
            continue
        out.append("-- " + intro)
        i += 1
        while i < len(code_lines) and (code_lines[i].startswith(" ") or not code_lines[i].strip()):
            if code_lines[i].strip():
                out.append("--   " + code_lines[i][2:])
            elif i + 1 < len(code_lines) and code_lines[i + 1].startswith(" "):
                out.append("--")
            else:
                break
            i += 1
    return out


def verso_line(source, name):
    """1-based line of the `:::::exercise … (name := "<name>")` directive."""
    if not source.exists():
        return None
    for i, line in enumerate(source.read_text().splitlines()):
        if "exercise" in line and f'(name := "{name}")' in line:
            return i + 1
    return None


class CodeBlocks(HTMLParser):
    """The Lean code blocks of a Verso page, in page order, as
    (text, whether it is inside an exercise or a quiz).  The text is what the
    reader sees: hover contents and the goal shown after each tactic are
    elements inside the block, and are left out."""

    VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link",
            "meta", "source", "track", "wbr"}
    SKIP = {"hover-container", "tactic-state"}
    OUTSIDE = {"exercise", "sf-quiz"}

    def __init__(self):
        super().__init__()
        self.classes = []   # the class lists of the open elements
        self.blocks = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        if tag in self.VOID:
            return
        classes = set((dict(attrs).get("class") or "").split())
        self.classes.append(classes)
        if self.current is None:
            if tag == "code" and {"hl", "lean", "block"} <= classes:
                inside = any(c & self.OUTSIDE for c in self.classes[:-1])
                self.current = {"depth": len(self.classes), "skip": None,
                                "text": [], "inside": inside}
        elif self.current["skip"] is None and classes & self.SKIP:
            self.current["skip"] = len(self.classes)

    def handle_endtag(self, tag):
        if tag in self.VOID or not self.classes:
            return
        depth = len(self.classes)
        self.classes.pop()
        if self.current is None:
            return
        if self.current["skip"] == depth:
            self.current["skip"] = None
        if self.current["depth"] == depth:
            self.blocks.append(("".join(self.current["text"]).strip("\n"),
                                self.current["inside"]))
            self.current = None

    def handle_data(self, data):
        if self.current is not None and self.current["skip"] is None:
            self.current["text"].append(data)


# SFLCompat's teaching commands, each followed by an indented block that the
# book shows as code of its own.
COMPAT_INDENTED = {"sf_expect_failure_in", "sf_experiment"}


def shown_lines(lines):
    """The chapter's lines as the book shows them in code blocks: the indented
    bodies of `sf_expect_failure_in` and `sf_experiment` without their indent.
    The body of an `sf_recall` is blanked: it restates a declaration that is
    already in the context where it stands, so it cannot be checked again."""
    out, owner = [], None
    for line in lines:
        if not line.strip():
            out.append("")
        elif not line.startswith((" ", "\t")):
            owner = line.rstrip()
            out.append(line)
        elif owner in COMPAT_INDENTED:
            out.append(line[2:])
        elif owner == "sf_recall":
            out.append("")
        else:
            out.append(line)
    return out


def block_name(code):
    """What a block declares, for the reader to recognize it by: the name of
    its first declaration, or the keyword of its first command."""
    for line in code.splitlines():
        if not line.strip() or line.lstrip().startswith("--"):
            continue
        m = re.match(r"(?:@\[[^\]]*\]\s*)?(?:(?:private|protected|noncomputable|"
                     r"partial|unsafe|nonrec|scoped|local)\s+)*([#\w]+)\s*([^\s:({\[⦃]*)", line)
        if not m:
            return "code"
        kw, name = m.groups()
        return name if name and kw in PROOF | {"def", "abbrev", "inductive", "structure",
                                                  "class", "axiom", "opaque"} else kw
    return "code"


def find_blocks(page, lines, offset_at, verso):
    """The code blocks of a chapter's page that can be checked on their own:
    those outside exercises and quizzes whose text stands as whole lines in
    the chapter's code.  Blocks are found in order, so a block whose text
    recurs is matched with its own occurrence."""
    if page is None or not page.exists():
        return []
    parser = CodeBlocks()
    parser.feed(page.read_text())
    shown = shown_lines(lines)
    text = "\n".join(shown)
    starts = [0]
    for line in shown:
        starts.append(starts[-1] + len(line) + 1)
    vtext = verso.read_text() if verso.exists() else ""
    vpos = pos = 0
    out = []
    for index, (code, inside) in enumerate(parser.blocks):
        if inside or not code.strip():
            continue
        at = pos
        while True:
            at = text.find(code, at)
            if at < 0 or ((at == 0 or text[at - 1] == "\n") and
                          text[at + len(code):at + len(code) + 1] in ("", "\n")):
                break
            at += 1
        if at < 0:
            continue
        pos = at + len(code)
        line = bisect.bisect_right(starts, at) - 1
        vat = vtext.find(code, vpos)
        if vat >= 0:
            vpos = vat + len(code)
        out.append({
            "index": index,
            "name": block_name(code),
            "code": code + "\n",
            "context": offset_at(line),
            "studentLine": line + 1,
            "sourcePath": str(verso),
            "sourceLine": vtext.count("\n", 0, vat) + 1 if vat >= 0 else None,
        })
    return out


def build_chapter(path, vol, page):
    lines = path.read_text().splitlines()
    imports, import_lines, body_start = chapter_header(lines)
    cmds = [(s + body_start, e + body_start) for s, e in split_commands(lines[body_start:])]
    exercises = find_exercises(lines)
    # Skeleton text, plus the offset at which each source line's command starts.
    parts, offsets = [], []
    pos = 0
    for s, e in cmds:
        offsets.append((s, pos))
        sk = skeleton_of_command(lines, s, e)
        if sk is not None:
            parts.append(sk + "\n\n")
            pos += len(parts[-1])
    skeleton = "".join(parts)

    def offset_at(line):
        off = pos
        for s, o in offsets:
            if s >= line:
                off = o
                break
        return off

    verso = Path(vol.upper()) / path.name
    ex_out = []
    for name, stars, flags, header, code, end in exercises:
        ex_out.append({
            "name": name,
            "stars": stars,
            "flags": [f.strip() for f in flags.split(",") if f.strip()],
            # The exercise occupies skeleton[context:contextEnd]; a reader's own
            # answer replaces that span when later exercises are checked.
            "context": offset_at(header),
            "contextEnd": offset_at(end),
            "code": "\n".join(compat_as_comment(trim_blank(lines[code:end]))) + "\n",
            "studentLine": header + 1,
            "sourcePath": str(verso),
            "sourceLine": verso_line(verso, name),
        })
    return {"imports": imports, "importLines": import_lines,
            "skeleton": skeleton, "exercises": ex_out,
            "blocks": find_blocks(page, lines, offset_at, verso)}


def import_closure(chapters, module, seen=None):
    """Chapters `module` depends on, dependencies first, excluding itself."""
    seen = [] if seen is None else seen
    for imp in chapters.get(module, {}).get("imports", []):
        if imp in chapters and imp not in seen:
            import_closure(chapters, imp, seen)
            seen.append(imp)
    return seen


def main():
    vol = sys.argv[1].lower()
    variant = sys.argv[2] if len(sys.argv) > 2 else "student"
    root = Path("_out") / vol / variant
    lean_dir = root / "lean" / vol.upper()
    out_dir = root / "html" / "sfl-lean" / "data"
    out_dir.mkdir(parents=True, exist_ok=True)

    chapters = {}
    for path in sorted(lean_dir.glob("*.lean")):
        page = root / "html" / path.stem / "index.html"
        chapters[f"{vol.upper()}.{path.stem}"] = build_chapter(path, vol, page)
    own = list(chapters)

    # A volume's generated project carries copies of the chapters it imports
    # from an earlier volume (HL imports LF.Typeclasses).  They join the
    # library like the volume's own chapters, but their pages and data files
    # belong to the other volume.
    pending = [imp for c in chapters.values() for imp in c["imports"]]
    while pending:
        module = pending.pop()
        path = root / "lean" / Path(*module.split(".")).with_suffix(".lean")
        if module in chapters or module.split(".")[0] == "SFLCompat" or not path.exists():
            continue
        chapters[module] = build_chapter(path, module.split(".")[0].lower(), None)
        pending += chapters[module]["imports"]

    for module in own:
        data = chapters[module]
        deps = import_closure(chapters, module)
        library = [{"module": d, "skeleton": chapters[d]["skeleton"],
                    "exercises": [{"name": e["name"], "context": e["context"],
                                   "contextEnd": e["contextEnd"]}
                                  for e in chapters[d]["exercises"]]}
                   for d in deps]
        # Imports from outside the book's own chapters (and outside SFLCompat,
        # whose commands the skeletons drop) are what the combined file needs.
        #
        # The combined file is an ordinary file, like the chapters that import
        # CustomTactics: joined into one module, their unexpanders and
        # `macro_rules` would have to be marked `meta`.  An ordinary file
        # accepts the `meta` and `public` that CustomTactics, a module, writes
        # on its declarations, but not on its imports, and it rejects
        # `import all` outright.  A chapter that reaches into another module's
        # private declarations stops the build here rather than leave the
        # exercises that include it failing in the reader's browser.
        externals = []
        for d in deps + [module]:
            for imp, line in zip(chapters[d]["imports"], chapters[d]["importLines"]):
                if imp in chapters or imp.split(".")[0] == "SFLCompat":
                    continue
                if re.search(r"\bimport\s+all\b", line):
                    sys.exit(
                        f"{d} has `{line}`.  The browser checks an exercise as one "
                        f"ordinary Lean file that holds every chapter it imports, and an "
                        f"ordinary file cannot use `import all`.  Copy the private "
                        f"declarations {d} needs from {imp} into {d} instead.")
                line = re.sub(r"^(?:public\s+)?(?:meta\s+)?import\b", "import", line)
                if line not in externals:
                    externals.append(line)
        chapter = module.split(".", 1)[1]
        payload = {
            "module": module,
            "chapter": chapter,
            "imports": externals,
            "library": library,
            "skeleton": data["skeleton"],
            "exercises": data["exercises"],
            "blocks": data["blocks"],
        }
        (out_dir / f"{chapter}.json").write_text(json.dumps(payload, ensure_ascii=False))
        print(f"{module}: {len(data['exercises'])} exercises, {len(data['blocks'])} blocks, "
              f"skeleton {len(data['skeleton'])} chars, {len(deps)} chapters before it")


if __name__ == "__main__":
    main()
